<?php require __DIR__.'/config.php';$err='';if($_SERVER['REQUEST_METHOD']==='POST'){if(!hash_equals($_SESSION['csrf']??'',$_POST['csrf']??'')){http_response_code(400);exit('CSRF');}$u=trim($_POST['username']??'');$c=trim($_POST['correo']??'');$p=$_POST['password']??'';if(!preg_match('/^[\pL\pN_.-]{3,32}$/u',$u)||!filter_var($c,FILTER_VALIDATE_EMAIL)||strlen($p)<8)$err='Revisa datos; contraseña de 8 caracteres mínimo.';else{try{$q=db()->prepare('INSERT INTO usuarios(username,correo,password_hash) VALUES(?,?,?)');$q->execute([$u,$c,password_hash($p,PASSWORD_DEFAULT)]);header('Location: login.php');exit;}catch(Throwable $e){$err='Username o correo ya usado.';}}}formpage('Crear cuenta');echo htmlspecialchars($err).'<form method="post"><input type="hidden" name="csrf" value="'.csrf().'"><input name="username" required placeholder="Username"><input name="correo" type="email" required placeholder="Correo"><input name="password" type="password" minlength="8" required placeholder="Contraseña"><button>Registrar</button></form><a href="login.php">Iniciar sesión</a></main>';